// Illustrative: train/val/test MSE for a polynomial fit via normal equations.
// Uses a tiny Gauss-Jordan solver to keep the example dependency free.
fn solve(mut a: Vec&lt;Vec&lt;f64&gt;&gt;, mut b: Vec&lt;f64&gt;) -&gt; Vec&lt;f64&gt; {
    let n = b.len();
    for c in 0..n {
        let piv = (c..n).max_by(|&i, &j| a[i][c].abs().total_cmp(&a[j][c].abs())).unwrap();
        a.swap(c, piv); b.swap(c, piv);
        let d = a[c][c];
        for j in 0..n { a[c][j] /= d; }
        b[c] /= d;
        for r in 0..n {
            if r != c {
                let f = a[r][c];
                for j in 0..n { a[r][j] -= f * a[c][j]; }
                b[r] -= f * b[c];
            }
        }
    }
    b
}

fn design(x: &[f64], d: usize) -&gt; Vec&lt;Vec&lt;f64&gt;&gt; {
    x.iter().map(|&xi| (0..=d).map(|k| xi.powi(k as i32)).collect()).collect()
}

fn mse(x: &[f64], y: &[f64], beta: &[f64], d: usize) -&gt; f64 {
    design(x, d).iter().zip(y).map(|(row, &yi)| {
        let pred: f64 = row.iter().zip(beta).map(|(a, b)| a * b).sum();
        (pred - yi).powi(2)
    }).sum::&lt;f64&gt;() / y.len() as f64
}

fn main() {
    // x, y, and split indices would be filled from data; shown schematically.
    let x_tr: Vec&lt;f64&gt; = vec![]; let y_tr: Vec&lt;f64&gt; = vec![];
    for d in 1..=15usize {
        let a = design(&x_tr, d);
        let p = d + 1;
        let mut ata = vec![vec![0.0; p]; p];
        let mut aty = vec![0.0; p];
        for (row, &yi) in a.iter().zip(&y_tr) {
            for i in 0..p {
                aty[i] += row[i] * yi;
                for j in 0..p { ata[i][j] += row[i] * row[j]; }
            }
        }
        if !y_tr.is_empty() {
            let beta = solve(ata, aty);
            println!("degree {d}: train mse {:.4}", mse(&x_tr, &y_tr, &beta, d));
        }
    }
}

