// Minimal OLS via the normal equations using nalgebra.
// Cargo.toml: nalgebra = "0.33", rand = "0.8", rand_distr = "0.4"
use nalgebra::{DMatrix, DVector};
use rand::SeedableRng;
use rand::rngs::StdRng;
use rand_distr::{Distribution, Normal};

fn main() {
    let mut rng = StdRng::seed_from_u64(0);
    let normal = Normal::new(0.0, 1.0).unwrap();
    let n = 200usize;

    let mut data = Vec::with_capacity(n * 4); // [1, x1, x2, x3]
    let mut y = Vec::with_capacity(n);
    for _ in 0..n {
        let x1 = normal.sample(&mut rng);
        let x2 = 0.9 * x1 + 0.4 * normal.sample(&mut rng);
        let x3 = normal.sample(&mut rng);
        let sigma = 0.5 + 0.6 * x1.abs();
        let yi = 2.0 + 1.5 * x1 + 0.8 * x1 * x1 - 1.0 * x3
            + sigma * normal.sample(&mut rng);
        data.extend_from_slice(&[1.0, x1, x2, x3]);
        y.push(yi);
    }
    let x = DMatrix::from_row_slice(n, 4, &data);
    let yv = DVector::from_vec(y);

    // beta_hat = (X'X)^-1 X'y
    let xtx = x.tr_mul(&x);
    let xty = x.tr_mul(&yv);
    let beta = xtx.try_inverse().expect("singular") * xty;
    println!("OLS coefficients: {}", beta.transpose());

    // Leverage diagonal trace should equal p+1 = 4
    let h = &x * xtx.try_inverse().unwrap() * x.transpose();
    let trace: f64 = (0..n).map(|i| h[(i, i)]).sum();
    println!("sum(h_ii) = {:.4} (p+1 = 4)", trace);
}

51.6 8. 구현
동반 라이브러리는 Python, Julia, Rust에 걸쳐 완전히 동일하며 종속성이 적은 소규모 추정기 구현체를 제공합니다. ch082_robust_regression 모듈은 fit_ols, fit_wls, fit_gls, fit_huber(Huber IRLS 핵심 루틴), fit_quantile, 그리고 vandermonde 기저 확장을 제공하며, 이들은 모두 공유되는 가중 정규 방정식 엔진과 처음부터 작성한 가우스 소거법 솔버를 기반으로 구축되었습니다. 이들은 설치 가능한 aiinaction(Python), AIInAction(Julia), aiinaction(Rust) 패키지의 일부이며, 다국어 동등성 테스트를 통해 세 언어의 구현이 아래에 사용된 고정 데이터에 대해 부동 소수점 오차 범위 내에서 일치함을 보장합니다.
이 예제는 정상적인 직선 \(y = 1 + 2x\)에 단 하나의 큰 이상치(gross outlier)를 오염시킵니다. 보통 최소제곱법(OLS)은 나쁜 데이터 포인트 쪽으로 심하게 끌려가는 반면, Huber 적합은 기저에 있는 직선을 거의 정확하게 복원하여 4.2.1절에서 유도한 영향력 제한(bounded-influence) 특성을 잘 보여줍니다.

