# A from-scratch bagging regressor, no ensemble helper
def bag_fit_predict(Xtr, ytr, Xte, B=100, seed=0):
    g = np.random.default_rng(seed)
    n = len(Xtr)
    preds = np.zeros((B, len(Xte)))
