        println!(
            "  {:?} =&gt; {:?} | conf={:.2} lift={:.2}",
            r.antecedent, r.consequent, r.confidence, r.lift
        );
    }
}

150.9 9. 구현
‘aiinaction’ 라이브러리는 세 가지 언어 모두에서 작고 종속성이 적은 AdaGrad 최적화 프로그램을 제공합니다. 상태는 매개변수 벡터 theta, 좌표별 누산기 G, 하이퍼 매개변수 eta 및 epsilon을 보유합니다. ’adagrad_step’은 한 번의 업데이트를 수행하고, ’valid_learning_rate’는 검사를 위해 ’eta / (sqrt(G) + epsilon)’을 노출하며, ’minimize’는 그래디언트 노름이 허용오차 아래로 떨어질 때까지 그래디언트 클로저에 대해 루프를 실행합니다. 아래 예는 기울기가 \(a_i(\theta_i - b_i)\)이고 최소값이 정확히 \(b\)인 분리 가능한 볼록 2차 \(f(\theta) = \tfrac{1}{2}\sum_i a_i(\theta_i - b_i)^2\)를 최소화합니다. 서로 다른 곡률 \(f(\theta) = \tfrac{1}{2}\sum_i a_i(\theta_i - b_i)^2\)는 단일 전역 단계 크기가 어려움을 겪는 고의적으로 조건이 나쁜 문제를 만드는 반면, AdaGrad는 세 좌표에 걸쳐 진행을 균등화합니다.

파이썬줄리아녹


from aiinaction.ch194_adagrad import (
    init_state,
    adagrad_step,
    effective_learning_rate,
    minimize,
    quadratic_grad,
)

a = [1.0, 4.0, 0.25]      # per-coordinate curvatures (ill-conditioned)
b = [2.0, -1.0, 5.0]      # the true minimizer
theta0 = [0.0, 0.0, 0.0]

# One update from the origin: note the per-coordinate effective rates differ.
state = init_state(theta0, learning_rate=0.5, epsilon=1e-8)
g0 = quadratic_grad(state.theta, a, b)
adagrad_step(state, g0)
print("gradient at start  :", [round(float(v), 4) for v in g0])
print("theta after 1 step :", [round(float(v), 6) for v in state.theta])
print("effective rates    :", [round(float(v), 6) for v in effective_learning_rate(state)])

# Full minimization converges to b despite the conditioning.
res = minimize(lambda th: quadratic_grad(th, a, b), theta0,
               learning_rate=0.5, epsilon=1e-8, max_iter=10000, tol=1e-9)
print("converged          :", res.converged, "in", res.n_steps, "steps")
print("recovered minimizer:", [round(float(v), 6) for v in res.theta])


