use aiinaction::ch194_adagrad::{
    adagrad_step, effective_learning_rate, init_state, minimize, quadratic_grad,
};

fn main() {
    let a = [1.0, 4.0, 0.25]; // per-coordinate curvatures (ill-conditioned)
    let b = [2.0, -1.0, 5.0]; // the true minimizer
    let theta0 = [0.0, 0.0, 0.0];

    // One update from the origin.
    let mut state = init_state(&theta0, 0.5, 1e-8).unwrap();
    let g0 = quadratic_grad(&state.theta, &a, &b).unwrap();
    adagrad_step(&mut state, &g0).unwrap();
    println!("gradient at start  : {:?}", g0);
    println!("theta after 1 step : {:?}", state.theta);
    println!("effective rates    : {:?}", effective_learning_rate(&state));

    // Full minimization.
    let grad = |th: &[f64]| quadratic_grad(th, &a, &b).unwrap();
    let res = minimize(grad, &theta0, 0.5, 1e-8, 10_000, 1e-9).unwrap();
    println!("converged          : {} in {} steps", res.converged, res.n_steps);
    println!("recovered minimizer: {:?}", res.theta);
}



