        ", uniform bound = ", round(xs.bound; digits=6))
println("He(relu)     std = ", round(hs.std; digits=6),
        ", uniform bound = ", round(hs.bound; digits=6))

W = he_normal(fan_in, fan_out; seed=0)          # (fan_out, fan_in)
target = 2.0 / fan_in
